    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        # Enumerate versions and absence for every package. The small published
        # bound (six packages, three versions each) makes exhaustive search apt.
        choices = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name])
            choices.append([-1] + versions)
        best = None
        best_vector = None

        def consider(assign):
            nonlocal best, best_vector
            installed = {name: version for name, version in assign.items() if version != -1}
            for name, bounds in roots.items():
                version = installed.get(name)
                if version is None or not bounds[0] <= version <= bounds[1]:
                    return
            edges = {name: [] for name in installed}
            for name, version in installed.items():
                if version in blocked.get(name, ()):
                    return
                if name in pins and pins[name] != version:
                    return
                row = next(row for row in packages[name] if row["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_version = installed.get(target)
                    if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                        return
                    edges[name].append(target)
            # Reject every directed cycle, including self-loops.
            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                if any(not visit(other) for other in edges[name]):
                    return False
                state[name] = 2
                return True
            if not all(visit(name) for name in installed):
                return
            vector = tuple(assign[name] for name in order)
            key = tuple(-v for v in vector) if maximize else vector
            if best_vector is None or key < best_vector:
                best_vector = key
                best = installed

        def enumerate_assign(i, assign):
            if i == len(names):
                consider(assign)
                return
            name = names[i]
            for version in choices[i]:
                assign[name] = version
                enumerate_assign(i + 1, assign)
            del assign[name]

        enumerate_assign(0, {})
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _ledger(data):
    rounding = data["rounding"]
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))

    def rounded(n, d):
        if rounding == "half_up":
            return (n + d // 2) // d
        return n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        valid = True
        for group, bounds in quotas.items():
            count = counts.get(group, 0)
            if not bounds[0] <= count <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in chosen)
        id_list = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bits.get(data["source"], 0)
    # State includes the visited set and coupons remaining; earliest arrival
    # dominates later arrivals for the same state because waiting is allowed.
    start_state = (data["source"], initial_mask, data["coupons"])
    dist = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and left == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), left - 1))
            for duration, next_left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_left))
    return {"arrival": None}


